DO $$ DECLARE v_def text; BEGIN SELECT pg_get_functiondef('public.guard_workspace_over_limit_write()'::regprocedure) INTO v_def; IF position('IF v_limit>0 AND v_used>=v_limit THEN' in v_def) = 0 THEN RAISE EXCEPTION 'Expected global plan guard condition was not found; no change applied'; END IF; v_def := replace(v_def, 'IF v_limit>0 AND v_used>=v_limit THEN', 'IF v_limit>0 AND v_used>v_limit THEN'); EXECUTE v_def; END $$;
